// The SQL workbench's task bank: realistic datasets (shop, HR, campus, flights, library, streaming, server logs, bank) with tasks from
// a plain SELECT up to window functions. Everything is deterministic: the same seed rebuilds the same data and the same task text, and the
// expected result is never written by hand, it is computed by running the reference query (see scripts/it-workbench-bulk.mts).
import { makeRng, type Rng } from "@/lib/workplace/rng";
import type { Cell, Dataset } from "@/lib/arena-workstations/engines/dataset";

export type Difficulty = "easy" | "medium" | "hard";

export interface SqlTaskDef {
  title: string;
  category: string;
  difficulty: Difficulty;
  /** what the student must produce, naming the columns, filters, order and rounding */
  prompt: string;
  /** the one SELECT that produces it */
  query: string;
  /** the rows must come back in this order (the task says so with ORDER BY) */
  ordered: boolean;
  tables: Dataset[];
  tags: string[];
}

type Col = Dataset["columns"][number];
const num = (name: string, description?: string): Col => ({ name, type: "number", description });
const txt = (name: string, description?: string): Col => ({ name, type: "text", description });
const date = (name: string, description?: string): Col => ({ name, type: "date", description });
const table = (name: string, columns: Col[], rows: Cell[][]): Dataset => ({ name, columns, rows });

const NAMES = ["Aarav", "Diya", "Kabir", "Meera", "Rohan", "Isha", "Vihaan", "Anaya", "Arjun", "Sara", "Neel", "Tara", "Dev", "Riya", "Kiran", "Maya", "Rahul", "Nisha", "Yash", "Pooja", "Imran", "Sneha", "Varun", "Lata", "Harsh", "Zoya", "Om", "Esha", "Karan", "Divya"];
const CITIES = ["Pune", "Chennai", "Jaipur", "Kochi", "Indore", "Nagpur"];
const person = (rng: Rng, i: number) => `${NAMES[i % NAMES.length]} ${rng.pick(["Rao", "Shah", "Nair", "Iyer", "Das", "Khan", "Patel", "Singh", "Reddy", "Menon"])}`;
const isoDate = (rng: Rng, from: string, days: number) => new Date(Date.parse(from) + rng.int(0, days) * 86_400_000).toISOString().slice(0, 10);

type Maker = (title: string, difficulty: Difficulty, category: string, prompt: string, query: string, ordered: boolean, tags?: string[]) => void;

function shop(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const customers = Array.from({ length: 22 }, (_, i) => [i + 1, person(rng, i), rng.pick(CITIES), isoDate(rng, "2025-01-01", 300)] as Cell[]);
  const catalog: [string, string, number][] = [["Notebook", "Stationery", 90], ["Pen set", "Stationery", 150], ["Backpack", "Bags", 1200], ["Laptop sleeve", "Bags", 800], ["Earbuds", "Audio", 1800], ["Speaker", "Audio", 3200], ["Desk lamp", "Home", 950], ["Mug", "Home", 320], ["Keyboard", "Computing", 2100], ["Mouse", "Computing", 750]];
  const products = catalog.map(([n, c, p], i) => [i + 1, n, c, p + rng.int(0, 5) * 10] as Cell[]);
  const orders = Array.from({ length: 55 }, (_, i) => [i + 1, rng.int(1, 18), isoDate(rng, "2025-03-01", 240), rng.weighted([["delivered", 7], ["cancelled", 1.5], ["pending", 1.5]] as const)] as Cell[]);
  const items = orders.flatMap((o) => Array.from({ length: rng.int(1, 3) }, () => [o[0], rng.int(1, 10), rng.int(1, 4)] as Cell[]));
  const t = [
    table("customers", [num("id"), txt("name"), txt("city"), date("joined_on")], customers),
    table("products", [num("id"), txt("name"), txt("category"), num("price", "rupees")], products),
    table("orders", [num("id"), num("customer_id"), date("order_date"), txt("status", "delivered, cancelled or pending")], orders),
    table("order_items", [num("order_id"), num("product_id"), num("qty")], items),
  ];
  tables(t);
  const city = rng.pick(CITIES.slice(0, 4));
  const cat = rng.pick(["Audio", "Computing", "Bags"]);
  const price = rng.pick([500, 800, 1000, 1500]);
  const k = rng.int(2, 4);
  add(`Customers from ${city}`, "easy", "SELECT & WHERE", `List the name and joined_on of every customer who lives in ${city}, in alphabetical order of name.`, `SELECT name, joined_on FROM customers WHERE city = '${city}' ORDER BY name`, true);
  add(`${cat} above ₹${price}`, "easy", "SELECT & WHERE", `List the name and price of products in the ${cat} category that cost more than ${price} rupees, most expensive first.`, `SELECT name, price FROM products WHERE category = '${cat}' AND price > ${price} ORDER BY price DESC, name`, true);
  add("Orders by status", "easy", "GROUP BY", "Count the orders in each status. Return status and order_count, with the biggest count first (ties by status name).", "SELECT status, COUNT(*) AS order_count FROM orders GROUP BY status ORDER BY order_count DESC, status", true);
  add("Revenue by category", "medium", "JOIN & aggregate", "For delivered orders only, find the revenue (price x qty) of each product category. Return category and revenue, rounded to 2 decimals, highest first.", "SELECT p.category, ROUND(SUM(p.price * oi.qty), 2) AS revenue FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'delivered' GROUP BY p.category ORDER BY revenue DESC", true);
  add("Customers who never ordered", "medium", "LEFT JOIN", "List the name of every customer who has not placed any order, in alphabetical order.", "SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL ORDER BY c.name", true);
  add("Top spenders", "medium", "JOIN & aggregate", `Find the ${k} customers who spent the most on delivered orders (price x qty). Return name and total_spent, highest first.`, `SELECT c.name, SUM(p.price * oi.qty) AS total_spent FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items oi ON oi.order_id = o.id JOIN products p ON p.id = oi.product_id WHERE o.status = 'delivered' GROUP BY c.id ORDER BY total_spent DESC, c.name LIMIT ${k}`, true);
  add("Orders per month", "medium", "Dates", "Count the orders placed in each month. Return month (as YYYY-MM) and order_count, in month order.", "SELECT strftime('%Y-%m', order_date) AS month, COUNT(*) AS order_count FROM orders GROUP BY month ORDER BY month", true);
  add("Repeat buyers", "hard", "HAVING & dates", "For customers with at least 2 orders, return name, first_order (earliest order_date), last_order (latest) and days_between (whole days between them). Order by days_between descending, then name.", "SELECT c.name, MIN(o.order_date) AS first_order, MAX(o.order_date) AS last_order, CAST(julianday(MAX(o.order_date)) - julianday(MIN(o.order_date)) AS INTEGER) AS days_between FROM customers c JOIN orders o ON o.customer_id = c.id GROUP BY c.id HAVING COUNT(*) >= 2 ORDER BY days_between DESC, c.name", true);
  add("Best seller in each category", "hard", "Window functions", "Using delivered orders, find the product with the highest units sold (sum of qty) in each category. Return category, product and units. If two products tie, keep the one that comes first alphabetically. Order by category.", "SELECT category, product, units FROM (SELECT p.category AS category, p.name AS product, SUM(oi.qty) AS units, ROW_NUMBER() OVER (PARTITION BY p.category ORDER BY SUM(oi.qty) DESC, p.name) AS rn FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'delivered' GROUP BY p.id) WHERE rn = 1 ORDER BY category", true);
  add("Running order count", "hard", "Window functions", "For each order date that has orders, return order_date, orders_that_day and running_total (orders up to and including that date). Show only the first 10 dates, oldest first.", "SELECT order_date, COUNT(*) AS orders_that_day, SUM(COUNT(*)) OVER (ORDER BY order_date) AS running_total FROM orders GROUP BY order_date ORDER BY order_date LIMIT 10", true);
}

function hr(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const depts = ["Engineering", "Sales", "Support", "Finance", "Design"].map((n, i) => [i + 1, n] as Cell[]);
  const emps: Cell[][] = [[1, "Meera Rao", 1, null, 240000, "2019-04-01"]];
  for (let i = 2; i <= 26; i++) emps.push([i, person(rng, i), rng.int(1, 5), i <= 6 ? 1 : rng.int(2, 6), rng.int(30, 140) * 1000, isoDate(rng, "2019-06-01", 2000)]);
  tables([table("departments", [num("id"), txt("name")], depts), table("employees", [num("id"), txt("name"), num("dept_id"), num("manager_id", "id of the manager, NULL for the head"), num("salary", "rupees per month"), date("hired_on")], emps)]);
  const min = rng.pick([60, 70, 80, 90]) * 1000;
  const d = rng.pick(["Engineering", "Sales", "Support"]);
  add(`Salaries above ₹${min / 1000}k`, "easy", "SELECT & WHERE", `List name and salary of employees earning more than ${min} a month, highest salary first (ties by name).`, `SELECT name, salary FROM employees WHERE salary > ${min} ORDER BY salary DESC, name`, true);
  add(`Who works in ${d}`, "easy", "JOIN", `List the names of employees in the ${d} department, alphabetically.`, `SELECT e.name FROM employees e JOIN departments d ON d.id = e.dept_id WHERE d.name = '${d}' ORDER BY e.name`, true);
  add("Headcount and payroll", "medium", "GROUP BY", "For each department return department name, headcount and total_payroll (sum of salary). Order by total_payroll descending.", "SELECT d.name AS department, COUNT(*) AS headcount, SUM(e.salary) AS total_payroll FROM employees e JOIN departments d ON d.id = e.dept_id GROUP BY d.id ORDER BY total_payroll DESC", true);
  add("Average salary by department", "medium", "GROUP BY", "Return each department's name and its average salary rounded to 0 decimals, only for departments averaging more than 70000. Order by the average, highest first.", "SELECT d.name AS department, ROUND(AVG(e.salary), 0) AS avg_salary FROM employees e JOIN departments d ON d.id = e.dept_id GROUP BY d.id HAVING AVG(e.salary) > 70000 ORDER BY avg_salary DESC", true);
  add("Employee and manager", "medium", "Self join", "List each employee who has a manager as employee and manager (both names). Order by employee name.", "SELECT e.name AS employee, m.name AS manager FROM employees e JOIN employees m ON m.id = e.manager_id ORDER BY e.name", true);
  add("Managers with the biggest teams", "medium", "Self join", "Return each manager's name and the number of direct reports (team_size) for managers with at least 3 reports. Biggest team first, ties by name.", "SELECT m.name AS manager, COUNT(*) AS team_size FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id HAVING COUNT(*) >= 3 ORDER BY team_size DESC, m.name", true);
  add("Earning above their department's average", "hard", "Subquery", "List name, department and salary of employees who earn more than the average salary of their own department. Order by department, then salary descending.", "SELECT e.name, d.name AS department, e.salary FROM employees e JOIN departments d ON d.id = e.dept_id WHERE e.salary > (SELECT AVG(salary) FROM employees WHERE dept_id = e.dept_id) ORDER BY department, e.salary DESC, e.name", true);
  add("Top two earners per department", "hard", "Window functions", "Return the two highest-paid employees of every department: department, name, salary, and salary_rank (1 or 2). Break ties by name. Order by department, then salary_rank.", "SELECT department, name, salary, salary_rank FROM (SELECT d.name AS department, e.name AS name, e.salary AS salary, ROW_NUMBER() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC, e.name) AS salary_rank FROM employees e JOIN departments d ON d.id = e.dept_id) WHERE salary_rank <= 2 ORDER BY department, salary_rank", true);
  add("Hires per year", "medium", "Dates", "Count how many employees were hired in each year. Return year (text) and hires, oldest year first.", "SELECT strftime('%Y', hired_on) AS year, COUNT(*) AS hires FROM employees GROUP BY year ORDER BY year", true);
  add("Gap to the department's top salary", "hard", "Window functions", "For every employee return name, salary and gap_to_top: how much less they earn than the highest salary in their own department. Show only employees with a gap above 0, biggest gap first, then name.", "SELECT name, salary, gap_to_top FROM (SELECT name, salary, MAX(salary) OVER (PARTITION BY dept_id) - salary AS gap_to_top FROM employees) WHERE gap_to_top > 0 ORDER BY gap_to_top DESC, name", true);
}

function campus(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const branches = ["CSE", "IT", "AI&ML", "DS"];
  const students = Array.from({ length: 24 }, (_, i) => [i + 1, person(rng, i), rng.pick(branches), rng.int(1, 4)] as Cell[]);
  const courses = [["Data Structures", 4], ["DBMS", 4], ["Operating Systems", 3], ["Computer Networks", 3], ["Machine Learning", 4], ["Web Technologies", 3], ["Discrete Maths", 3]].map(([t, c], i) => [i + 1, t, c] as Cell[]);
  const enr: Cell[][] = [];
  for (const s of students.slice(0, 21)) for (const c of rng.shuffle(courses).slice(0, rng.int(2, 5))) enr.push([s[0], c[0], rng.int(4, 10), rng.pick(["Sem 3", "Sem 4", "Sem 5"])]);
  tables([table("students", [num("id"), txt("name"), txt("branch"), num("year")], students), table("courses", [num("id"), txt("title"), num("credits")], courses), table("enrollments", [num("student_id"), num("course_id"), num("grade_points", "out of 10"), txt("semester")], enr)]);
  const b = rng.pick(branches);
  const g = rng.int(7, 9);
  add(`${b} students`, "easy", "SELECT & WHERE", `List the name and year of every ${b} student, ordered by year then name.`, `SELECT name, year FROM students WHERE branch = '${b}' ORDER BY year, name`, true);
  add("Enrolments per course", "easy", "GROUP BY", "Count the students enrolled in each course. Return title and enrolled, most popular first, ties by title.", "SELECT c.title, COUNT(*) AS enrolled FROM enrollments e JOIN courses c ON c.id = e.course_id GROUP BY c.id ORDER BY enrolled DESC, c.title", true);
  add(`Scored ${g}+ in a course`, "medium", "JOIN", `List each student name with the course title where they scored at least ${g} grade points. Order by name, then title.`, `SELECT s.name, c.title FROM enrollments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id WHERE e.grade_points >= ${g} ORDER BY s.name, c.title`, true);
  add("CGPA", "medium", "Weighted average", "Compute each student's CGPA: the credit-weighted average of grade_points (sum of grade_points x credits divided by sum of credits), rounded to 2 decimals. Return name and cgpa, highest first, ties by name.", "SELECT s.name, ROUND(SUM(e.grade_points * c.credits) * 1.0 / SUM(c.credits), 2) AS cgpa FROM enrollments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.id ORDER BY cgpa DESC, s.name", true);
  add("Not enrolled in anything", "medium", "LEFT JOIN", "List the names of students with no enrolment at all, alphabetically.", "SELECT s.name FROM students s LEFT JOIN enrollments e ON e.student_id = s.id WHERE e.student_id IS NULL ORDER BY s.name", true);
  add("Hardest courses", "medium", "HAVING", "For courses with at least 3 enrolments return title and avg_grade (average grade_points, 2 decimals), lowest average first.", "SELECT c.title, ROUND(AVG(e.grade_points), 2) AS avg_grade FROM enrollments e JOIN courses c ON c.id = e.course_id GROUP BY c.id HAVING COUNT(*) >= 3 ORDER BY avg_grade, c.title", true);
  add("Topper of each branch", "hard", "Window functions", "Using each student's average grade_points (not credit-weighted), return the top student of every branch: branch, name and avg_grade (2 decimals). Ties go to the alphabetically first name. Order by branch.", "SELECT branch, name, avg_grade FROM (SELECT s.branch AS branch, s.name AS name, ROUND(AVG(e.grade_points), 2) AS avg_grade, ROW_NUMBER() OVER (PARTITION BY s.branch ORDER BY AVG(e.grade_points) DESC, s.name) AS rn FROM enrollments e JOIN students s ON s.id = e.student_id GROUP BY s.id) WHERE rn = 1 ORDER BY branch", true);
  add("Above the course average", "hard", "Subquery", "List student name, course title and grade_points for every enrolment scoring at least 2 grade points above that course's average. Order by title, grade_points descending, name.", "SELECT s.name, c.title, e.grade_points FROM enrollments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id WHERE e.grade_points >= (SELECT AVG(grade_points) FROM enrollments WHERE course_id = e.course_id) + 2 ORDER BY c.title, e.grade_points DESC, s.name", true);
  add("Students taking both DBMS and Data Structures", "hard", "Set logic", "List the names of students enrolled in both DBMS and Data Structures, alphabetically.", "SELECT s.name FROM students s WHERE s.id IN (SELECT e.student_id FROM enrollments e JOIN courses c ON c.id = e.course_id WHERE c.title = 'DBMS') AND s.id IN (SELECT e.student_id FROM enrollments e JOIN courses c ON c.id = e.course_id WHERE c.title = 'Data Structures') ORDER BY s.name", true);
}

function flights(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const route: [string, string][] = [["Pune", "Delhi"], ["Delhi", "Chennai"], ["Chennai", "Kochi"], ["Mumbai", "Jaipur"], ["Kochi", "Pune"], ["Delhi", "Mumbai"]];
  const fl = Array.from({ length: 24 }, (_, i) => { const r = rng.pick(route); return [i + 1, r[0], r[1], isoDate(rng, "2026-01-01", 120), rng.int(20, 90) * 100, 120 + rng.int(0, 6) * 10] as Cell[]; });
  const bk = Array.from({ length: 70 }, (_, i) => [i + 1, rng.int(1, 24), person(rng, i), rng.int(1, 4), rng.chance(0.15) ? "cancelled" : "confirmed"] as Cell[]);
  tables([table("flights", [num("id"), txt("origin"), txt("destination"), date("depart_date"), num("fare", "rupees per seat"), num("seats", "seats on the aircraft")], fl), table("bookings", [num("id"), num("flight_id"), txt("passenger"), num("seats_booked"), txt("status", "confirmed or cancelled")], bk)]);
  const o = rng.pick(["Pune", "Delhi", "Chennai"]);
  const f = rng.pick([3000, 4000, 5000]);
  add(`Flights out of ${o}`, "easy", "SELECT & WHERE", `List id, destination and fare of flights departing from ${o}, cheapest first (ties by id).`, `SELECT id, destination, fare FROM flights WHERE origin = '${o}' ORDER BY fare, id`, true);
  add(`Fares under ₹${f}`, "easy", "SELECT & WHERE", `Count the flights with a fare below ${f}. Return a single column named cheap_flights.`, `SELECT COUNT(*) AS cheap_flights FROM flights WHERE fare < ${f}`, false);
  add("Seats sold per flight", "medium", "JOIN & aggregate", "Using confirmed bookings only, return flight id and seats_sold (sum of seats_booked) for flights that have any. Order by seats_sold descending, then id.", "SELECT f.id, SUM(b.seats_booked) AS seats_sold FROM flights f JOIN bookings b ON b.flight_id = f.id WHERE b.status = 'confirmed' GROUP BY f.id ORDER BY seats_sold DESC, f.id", true);
  add("Revenue by route", "medium", "JOIN & aggregate", "Using confirmed bookings, compute revenue (fare x seats_booked) per route. Return origin, destination and revenue, highest first, ties by origin then destination.", "SELECT f.origin, f.destination, SUM(f.fare * b.seats_booked) AS revenue FROM flights f JOIN bookings b ON b.flight_id = f.id WHERE b.status = 'confirmed' GROUP BY f.origin, f.destination ORDER BY revenue DESC, f.origin, f.destination", true);
  add("Flights with no confirmed booking", "medium", "NOT EXISTS", "List the id and route (origin, destination) of flights that have no confirmed booking. Order by id.", "SELECT id, origin, destination FROM flights f WHERE NOT EXISTS (SELECT 1 FROM bookings b WHERE b.flight_id = f.id AND b.status = 'confirmed') ORDER BY id", true);
  add("Cancellation rate", "medium", "Conditional aggregate", "For each origin return origin and cancel_rate: cancelled bookings as a percentage of all bookings on flights from that origin, rounded to 1 decimal. Order by cancel_rate descending, then origin.", "SELECT f.origin, ROUND(100.0 * SUM(CASE WHEN b.status = 'cancelled' THEN 1 ELSE 0 END) / COUNT(*), 1) AS cancel_rate FROM flights f JOIN bookings b ON b.flight_id = f.id GROUP BY f.origin ORDER BY cancel_rate DESC, f.origin", true);
  add("Nearly full flights", "hard", "HAVING", "Find flights where confirmed seats_booked add up to at least 10 seats. Return id, seats_sold and seats, ordered by id.", "SELECT f.id, SUM(b.seats_booked) AS seats_sold, f.seats FROM flights f JOIN bookings b ON b.flight_id = f.id WHERE b.status = 'confirmed' GROUP BY f.id HAVING SUM(b.seats_booked) >= 10 ORDER BY f.id", true);
  add("Cheapest flight on each route", "hard", "Window functions", "For every (origin, destination) route return the cheapest flight: origin, destination, id and fare. Ties go to the lowest id. Order by origin, destination.", "SELECT origin, destination, id, fare FROM (SELECT origin, destination, id, fare, ROW_NUMBER() OVER (PARTITION BY origin, destination ORDER BY fare, id) AS rn FROM flights) WHERE rn = 1 ORDER BY origin, destination", true);
  add("Passengers with several bookings", "medium", "HAVING", "List passengers who made at least 2 confirmed bookings, with bookings count. Order by count descending, then passenger.", "SELECT passenger, COUNT(*) AS bookings FROM bookings WHERE status = 'confirmed' GROUP BY passenger HAVING COUNT(*) >= 2 ORDER BY bookings DESC, passenger", true);
}

function library(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const titles = ["Clean Code", "Dune", "Sapiens", "The Pragmatic Programmer", "Atomic Habits", "Neuromancer", "Algorithms", "Deep Work", "Foundation", "The Mythical Man-Month", "Zero to One", "Snow Crash"];
  const genres = ["Tech", "Fiction", "History", "Tech", "Self-help", "Fiction", "Tech", "Self-help", "Fiction", "Tech", "Business", "Fiction"];
  const books = titles.map((t, i) => [i + 1, t, genres[i], 1975 + rng.int(0, 48)] as Cell[]);
  const members = Array.from({ length: 16 }, (_, i) => [i + 1, person(rng, i + 3)] as Cell[]);
  const loans = Array.from({ length: 60 }, (_, i) => { const out = isoDate(rng, "2026-01-01", 150); const late = rng.chance(0.3); const back = rng.chance(0.8) ? new Date(Date.parse(out) + (late ? rng.int(15, 30) : rng.int(3, 14)) * 86_400_000).toISOString().slice(0, 10) : null; return [i + 1, rng.int(1, 10), rng.int(1, 16), out, back] as Cell[]; });
  tables([table("books", [num("id"), txt("title"), txt("genre"), num("published_year")], books), table("members", [num("id"), txt("name")], members), table("loans", [num("id"), num("book_id"), num("member_id"), date("loaned_on"), date("returned_on", "NULL while the book is still out")], loans)]);
  const g = rng.pick(["Tech", "Fiction"]);
  add(`${g} books, newest first`, "easy", "SELECT & WHERE", `List the title and published_year of ${g} books, newest first (ties by title).`, `SELECT title, published_year FROM books WHERE genre = '${g}' ORDER BY published_year DESC, title`, true);
  add("Books currently out", "easy", "NULL handling", "List the titles of books that are currently on loan (returned_on is NULL), alphabetically, each title once.", "SELECT DISTINCT b.title FROM loans l JOIN books b ON b.id = l.book_id WHERE l.returned_on IS NULL ORDER BY b.title", true);
  add("Loans per genre", "medium", "GROUP BY", "Count the loans per genre. Return genre and loans, highest first, ties by genre.", "SELECT b.genre, COUNT(*) AS loans FROM loans l JOIN books b ON b.id = l.book_id GROUP BY b.genre ORDER BY loans DESC, b.genre", true);
  add("Never borrowed", "medium", "LEFT JOIN", "List the titles of books that have never been loaned, alphabetically.", "SELECT b.title FROM books b LEFT JOIN loans l ON l.book_id = b.id WHERE l.id IS NULL ORDER BY b.title", true);
  add("Late returns", "medium", "Dates", "A book is late if it came back more than 14 days after loaned_on. List member name, book title and days_kept (whole days) for late returns, longest first, ties by name.", "SELECT m.name, b.title, CAST(julianday(l.returned_on) - julianday(l.loaned_on) AS INTEGER) AS days_kept FROM loans l JOIN members m ON m.id = l.member_id JOIN books b ON b.id = l.book_id WHERE l.returned_on IS NOT NULL AND julianday(l.returned_on) - julianday(l.loaned_on) > 14 ORDER BY days_kept DESC, m.name, b.title", true);
  add("Most active readers", "medium", "GROUP BY", "Return the 5 members with the most loans: name and loans. Ties by name.", "SELECT m.name, COUNT(*) AS loans FROM loans l JOIN members m ON m.id = l.member_id GROUP BY m.id ORDER BY loans DESC, m.name LIMIT 5", true);
  add("Average loan length", "hard", "Dates & CASE", "For each genre return avg_days: the average number of days between loaned_on and returned_on over returned loans, 1 decimal. Order by avg_days descending, then genre.", "SELECT b.genre, ROUND(AVG(julianday(l.returned_on) - julianday(l.loaned_on)), 1) AS avg_days FROM loans l JOIN books b ON b.id = l.book_id WHERE l.returned_on IS NOT NULL GROUP BY b.genre ORDER BY avg_days DESC, b.genre", true);
  add("Each member's latest loan", "hard", "Window functions", "For every member who has loaned something, return name, title of their most recent loan and loaned_on. If two loans share a date take the lower loan id. Order by name.", "SELECT name, title, loaned_on FROM (SELECT m.name AS name, b.title AS title, l.loaned_on AS loaned_on, ROW_NUMBER() OVER (PARTITION BY l.member_id ORDER BY l.loaned_on DESC, l.id) AS rn FROM loans l JOIN members m ON m.id = l.member_id JOIN books b ON b.id = l.book_id) WHERE rn = 1 ORDER BY name", true);
  add("Genres by share of loans", "hard", "Window functions", "Return genre, loans and share: that genre's percentage of all loans, rounded to 1 decimal. Order by share descending, then genre.", "SELECT b.genre, COUNT(*) AS loans, ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS share FROM loans l JOIN books b ON b.id = l.book_id GROUP BY b.genre ORDER BY share DESC, b.genre", true);
}

function streaming(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const users = Array.from({ length: 20 }, (_, i) => [i + 1, person(rng, i + 6), rng.weighted([["free", 5], ["basic", 3], ["premium", 2]] as const), rng.pick(["India", "UAE", "UK", "USA"])] as Cell[]);
  const shows = ["Night Shift", "Code Red", "Lost Signal", "Paper Towns", "The Grid", "Monsoon", "Deep Blue", "Last Stop"];
  const plays = Array.from({ length: 90 }, (_, i) => [i + 1, rng.int(1, 17), rng.pick(shows), rng.int(5, 120), isoDate(rng, "2026-02-01", 90)] as Cell[]);
  tables([table("users", [num("id"), txt("name"), txt("plan", "free, basic or premium"), txt("country")], users), table("plays", [num("id"), num("user_id"), txt("title"), num("minutes"), date("played_on")], plays)]);
  const p = rng.pick(["premium", "basic"]);
  const m = rng.pick([60, 90, 100]);
  add(`${p} members`, "easy", "SELECT & WHERE", `List the names and countries of users on the ${p} plan, ordered by country then name.`, `SELECT name, country FROM users WHERE plan = '${p}' ORDER BY country, name`, true);
  add("Total watch time per title", "easy", "GROUP BY", "Return each title with total_minutes, longest first, ties by title.", "SELECT title, SUM(minutes) AS total_minutes FROM plays GROUP BY title ORDER BY total_minutes DESC, title", true);
  add(`Long sessions (${m}+ min)`, "easy", "SELECT & WHERE", `Count the plays that lasted at least ${m} minutes. Return one column named long_sessions.`, `SELECT COUNT(*) AS long_sessions FROM plays WHERE minutes >= ${m}`, false);
  add("Minutes by plan", "medium", "JOIN & aggregate", "Return each plan with total_minutes and viewers (distinct users who played anything). Order by total_minutes descending.", "SELECT u.plan, SUM(p.minutes) AS total_minutes, COUNT(DISTINCT p.user_id) AS viewers FROM plays p JOIN users u ON u.id = p.user_id GROUP BY u.plan ORDER BY total_minutes DESC", true);
  add("Users who never played", "medium", "LEFT JOIN", "List names of users with no plays, alphabetically.", "SELECT u.name FROM users u LEFT JOIN plays p ON p.user_id = u.id WHERE p.id IS NULL ORDER BY u.name", true);
  add("Weekly minutes", "medium", "Dates", "Return week (strftime '%Y-%W') and minutes watched in that week, oldest week first.", "SELECT strftime('%Y-%W', played_on) AS week, SUM(minutes) AS minutes FROM plays GROUP BY week ORDER BY week", true);
  add("Most-watched title per country", "hard", "Window functions", "For each country return the title with the most total minutes watched by its users: country, title, minutes. Ties go to the alphabetically first title. Order by country.", "SELECT country, title, minutes FROM (SELECT u.country AS country, p.title AS title, SUM(p.minutes) AS minutes, ROW_NUMBER() OVER (PARTITION BY u.country ORDER BY SUM(p.minutes) DESC, p.title) AS rn FROM plays p JOIN users u ON u.id = p.user_id GROUP BY u.country, p.title) WHERE rn = 1 ORDER BY country", true);
  add("Heavy viewers", "hard", "HAVING", "A heavy viewer has watched at least 300 minutes in total. List user name, total_minutes and titles_watched (distinct titles) for heavy viewers, ordered by total_minutes descending, then name.", "SELECT u.name, SUM(p.minutes) AS total_minutes, COUNT(DISTINCT p.title) AS titles_watched FROM plays p JOIN users u ON u.id = p.user_id GROUP BY u.id HAVING SUM(p.minutes) >= 300 ORDER BY total_minutes DESC, u.name", true);
  add("Each user's first title", "hard", "Window functions", "For every user who played anything return name and the title they played first (earliest played_on, ties by lowest play id). Order by name.", "SELECT name, title FROM (SELECT u.name AS name, p.title AS title, ROW_NUMBER() OVER (PARTITION BY p.user_id ORDER BY p.played_on, p.id) AS rn FROM plays p JOIN users u ON u.id = p.user_id) WHERE rn = 1 ORDER BY name", true);
  add("Titles watched by premium and free users", "hard", "Set logic", "List titles that were played by at least one premium user and at least one free user, alphabetically.", "SELECT title FROM plays p JOIN users u ON u.id = p.user_id GROUP BY title HAVING SUM(u.plan = 'premium') > 0 AND SUM(u.plan = 'free') > 0 ORDER BY title", true);
}

function logs(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const svc = ["auth", "payments", "search", "feed", "uploads"];
  const rows = Array.from({ length: 100 }, (_, i) => [i + 1, rng.pick(svc), rng.weighted([["INFO", 7], ["WARN", 2], ["ERROR", 1.2]] as const), rng.int(8, 900), isoDate(rng, "2026-03-01", 30)] as Cell[]);
  tables([table("requests", [num("id"), txt("service"), txt("level", "INFO, WARN or ERROR"), num("latency_ms"), date("logged_on")], rows)]);
  const s = rng.pick(svc);
  const ms = rng.pick([300, 400, 500]);
  add(`Slow ${s} requests`, "easy", "SELECT & WHERE", `List id and latency_ms of ${s} requests slower than ${ms} ms, slowest first (ties by id).`, `SELECT id, latency_ms FROM requests WHERE service = '${s}' AND latency_ms > ${ms} ORDER BY latency_ms DESC, id`, true);
  add("Errors per service", "easy", "GROUP BY", "Count ERROR-level requests per service. Return service and errors for services that have any, most errors first, ties by service.", "SELECT service, COUNT(*) AS errors FROM requests WHERE level = 'ERROR' GROUP BY service ORDER BY errors DESC, service", true);
  add("Average latency", "medium", "GROUP BY", "Return each service with avg_latency (average latency_ms, 1 decimal) and requests, slowest average first.", "SELECT service, ROUND(AVG(latency_ms), 1) AS avg_latency, COUNT(*) AS requests FROM requests GROUP BY service ORDER BY avg_latency DESC, service", true);
  add("Error rate", "medium", "Conditional aggregate", "For each service return error_pct: ERROR requests as a percentage of all its requests, 1 decimal. Highest first, ties by service.", "SELECT service, ROUND(100.0 * SUM(CASE WHEN level = 'ERROR' THEN 1 ELSE 0 END) / COUNT(*), 1) AS error_pct FROM requests GROUP BY service ORDER BY error_pct DESC, service", true);
  add("Busiest days", "medium", "GROUP BY", "Return the 5 days with the most requests: logged_on and requests. Ties by date.", "SELECT logged_on, COUNT(*) AS requests FROM requests GROUP BY logged_on ORDER BY requests DESC, logged_on LIMIT 5", true);
  add("Slowest requests per service", "hard", "Window functions", "For each service return the slowest 2 requests: service, id, latency_ms and position (1 or 2). Ties by lowest id. Order by service, position.", "SELECT service, id, latency_ms, position FROM (SELECT service, id, latency_ms, ROW_NUMBER() OVER (PARTITION BY service ORDER BY latency_ms DESC, id) AS position FROM requests) WHERE position <= 2 ORDER BY service, position", true);
  add("Services with many slow requests", "hard", "Subquery", "Return each service where more than 40% of its requests took 400 ms or more: service and slow_pct (percentage, 1 decimal). Order by slow_pct descending, then service.", "SELECT service, ROUND(100.0 * SUM(CASE WHEN latency_ms >= 400 THEN 1 ELSE 0 END) / COUNT(*), 1) AS slow_pct FROM requests GROUP BY service HAVING 100.0 * SUM(CASE WHEN latency_ms >= 400 THEN 1 ELSE 0 END) / COUNT(*) > 40 ORDER BY slow_pct DESC, service", true);
  add("Worst day for errors", "hard", "Subquery", "For each service that had any ERROR, return the day with the most errors: service, logged_on and errors (lowest date on a tie). Order by service.", "SELECT service, logged_on, errors FROM (SELECT service, logged_on, COUNT(*) AS errors, ROW_NUMBER() OVER (PARTITION BY service ORDER BY COUNT(*) DESC, logged_on) AS rn FROM requests WHERE level = 'ERROR' GROUP BY service, logged_on) WHERE rn = 1 ORDER BY service", true);
  add("Latency buckets", "medium", "CASE", "Classify each request as 'fast' (under 100 ms), 'ok' (100 to 399) or 'slow' (400 and above). Return bucket and requests, most requests first, ties by bucket.", "SELECT CASE WHEN latency_ms < 100 THEN 'fast' WHEN latency_ms < 400 THEN 'ok' ELSE 'slow' END AS bucket, COUNT(*) AS requests FROM requests GROUP BY bucket ORDER BY requests DESC, bucket", true);
  add("Rolling three-day requests", "hard", "Window functions", "Return logged_on, requests that day, and rolling_3 (requests on that day and the two days before it in the list of days that have data). Show only the first 10 days, oldest first.", "SELECT logged_on, requests, SUM(requests) OVER (ORDER BY logged_on ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS rolling_3 FROM (SELECT logged_on, COUNT(*) AS requests FROM requests GROUP BY logged_on) ORDER BY logged_on LIMIT 10", true);
}

function bank(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const accounts = Array.from({ length: 18 }, (_, i) => [i + 1, person(rng, i + 9), rng.pick(["savings", "current"]), rng.int(5, 400) * 1000] as Cell[]);
  const txns = Array.from({ length: 80 }, (_, i) => { const kind = rng.weighted([["deposit", 4], ["withdrawal", 4], ["fee", 1]] as const); return [i + 1, rng.int(1, 15), kind === "fee" ? rng.int(1, 5) * 50 : rng.int(1, 40) * 500, kind, isoDate(rng, "2026-01-01", 180)] as Cell[]; });
  for (const acct of [16, 17]) for (let k = 0; k < 2; k++) txns.push([txns.length + 1, acct, rng.int(2, 30) * 500, "deposit", isoDate(rng, "2026-01-01", 180)]);
  tables([table("accounts", [num("id"), txt("holder"), txt("type", "savings or current"), num("balance", "rupees")], accounts), table("transactions", [num("id"), num("account_id"), num("amount", "always positive"), txt("kind", "deposit, withdrawal or fee"), date("txn_date")], txns)]);
  const t = rng.pick(["savings", "current"]);
  const b = rng.pick([100, 150, 200]) * 1000;
  add(`${t} accounts over ₹${b / 1000}k`, "easy", "SELECT & WHERE", `List holder and balance of ${t} accounts with a balance above ${b}, richest first (ties by holder).`, `SELECT holder, balance FROM accounts WHERE type = '${t}' AND balance > ${b} ORDER BY balance DESC, holder`, true);
  add("Money moved by kind", "easy", "GROUP BY", "Return each transaction kind with count and total_amount. Highest total first.", "SELECT kind, COUNT(*) AS count, SUM(amount) AS total_amount FROM transactions GROUP BY kind ORDER BY total_amount DESC, kind", true);
  add("Net movement per account", "medium", "CASE", "Net movement of an account is deposits minus withdrawals minus fees. Return holder and net_movement for accounts with at least one transaction, highest first, ties by holder.", "SELECT a.holder, SUM(CASE WHEN t.kind = 'deposit' THEN t.amount ELSE -t.amount END) AS net_movement FROM accounts a JOIN transactions t ON t.account_id = a.id GROUP BY a.id ORDER BY net_movement DESC, a.holder", true);
  add("Quiet accounts", "medium", "LEFT JOIN", "List the holder of every account that has no transaction, alphabetically.", "SELECT a.holder FROM accounts a LEFT JOIN transactions t ON t.account_id = a.id WHERE t.id IS NULL ORDER BY a.holder", true);
  add("Fees by type", "medium", "JOIN & aggregate", "Total fees charged per account type: type and total_fees (fees only). Highest first.", "SELECT a.type, SUM(t.amount) AS total_fees FROM transactions t JOIN accounts a ON a.id = t.account_id WHERE t.kind = 'fee' GROUP BY a.type ORDER BY total_fees DESC, a.type", true);
  add("Large withdrawals", "medium", "Subquery", "List holder, amount and txn_date of withdrawals larger than the average withdrawal. Order by amount descending, then holder, then date.", "SELECT a.holder, t.amount, t.txn_date FROM transactions t JOIN accounts a ON a.id = t.account_id WHERE t.kind = 'withdrawal' AND t.amount > (SELECT AVG(amount) FROM transactions WHERE kind = 'withdrawal') ORDER BY t.amount DESC, a.holder, t.txn_date", true);
  add("Running balance of one account", "hard", "Window functions", "For the account with the most transactions (lowest id on a tie) return txn_date, kind, amount and running_net (cumulative deposits minus withdrawals and fees in order of date, ties by transaction id). Oldest first.", "SELECT txn_date, kind, amount, SUM(CASE WHEN kind = 'deposit' THEN amount ELSE -amount END) OVER (ORDER BY txn_date, id) AS running_net FROM transactions WHERE account_id = (SELECT account_id FROM transactions GROUP BY account_id ORDER BY COUNT(*) DESC, account_id LIMIT 1) ORDER BY txn_date, id", true);
  add("Biggest transaction per account", "hard", "Window functions", "For each account with transactions return holder, its largest amount and the kind of that transaction (lowest id on a tie). Order by holder.", "SELECT holder, amount, kind FROM (SELECT a.holder AS holder, t.amount AS amount, t.kind AS kind, ROW_NUMBER() OVER (PARTITION BY a.id ORDER BY t.amount DESC, t.id) AS rn FROM transactions t JOIN accounts a ON a.id = t.account_id) WHERE rn = 1 ORDER BY holder", true);
  add("Accounts that only deposit", "hard", "Set logic", "List the holders of accounts that have at least one deposit and no withdrawals or fees. Alphabetical.", "SELECT a.holder FROM accounts a WHERE EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.kind = 'deposit') AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.kind <> 'deposit') ORDER BY a.holder", true);
  add("Monthly deposits", "medium", "Dates", "Return month (YYYY-MM) and total deposits that month, oldest month first.", "SELECT strftime('%Y-%m', txn_date) AS month, SUM(amount) AS deposits FROM transactions WHERE kind = 'deposit' GROUP BY month ORDER BY month", true);
}


function hospital(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const patients = Array.from({ length: 24 }, (_, i) => [i + 1, person(rng, i + 2), rng.int(5, 80), rng.pick(CITIES)] as Cell[]);
  const specs = ["Cardiology", "Orthopaedics", "Paediatrics", "Dermatology", "General"];
  const doctors = specs.flatMap((sp, i) => [[i * 2 + 1, person(rng, i * 2 + 11), sp] as Cell[], [i * 2 + 2, person(rng, i * 2 + 12), sp] as Cell[]]);
  const visits = Array.from({ length: 80 }, (_, i) => [i + 1, rng.int(1, 20), rng.int(1, 10), isoDate(rng, "2026-01-01", 200), rng.int(3, 20) * 100, rng.weighted([["completed", 8], ["cancelled", 2]] as const)] as Cell[]);
  tables([table("patients", [num("id"), txt("name"), num("age"), txt("city")], patients), table("doctors", [num("id"), txt("name"), txt("specialty")], doctors), table("visits", [num("id"), num("patient_id"), num("doctor_id"), date("visit_date"), num("fee", "rupees"), txt("status", "completed or cancelled")], visits)]);
  const age = rng.pick([40, 50, 60, 65]);
  add(`Patients over ${age}`, "easy", "SELECT & WHERE", `List the name and age of patients older than ${age}, oldest first (ties by name).`, `SELECT name, age FROM patients WHERE age > ${age} ORDER BY age DESC, name`, true);
  add("Visits per specialty", "easy", "JOIN & aggregate", "Count the visits (any status) for each specialty. Return specialty and visits, most visits first, ties by specialty.", "SELECT d.specialty, COUNT(*) AS visits FROM visits v JOIN doctors d ON d.id = v.doctor_id GROUP BY d.specialty ORDER BY visits DESC, d.specialty", true);
  add("Top earning doctors", "medium", "JOIN & aggregate", "Using completed visits only, return the 5 doctors who earned the most in fees: name and total_fees. Ties by name.", "SELECT d.name, SUM(v.fee) AS total_fees FROM visits v JOIN doctors d ON d.id = v.doctor_id WHERE v.status = 'completed' GROUP BY d.id ORDER BY total_fees DESC, d.name LIMIT 5", true);
  add("Patients never seen", "medium", "LEFT JOIN", "List the names of patients with no visit at all, alphabetically.", "SELECT p.name FROM patients p LEFT JOIN visits v ON v.patient_id = p.id WHERE v.id IS NULL ORDER BY p.name", true);
  add("Average fee per specialty", "medium", "GROUP BY", "For completed visits return each specialty with avg_fee (rounded to 1 decimal). Highest first, ties by specialty.", "SELECT d.specialty, ROUND(AVG(v.fee), 1) AS avg_fee FROM visits v JOIN doctors d ON d.id = v.doctor_id WHERE v.status = 'completed' GROUP BY d.specialty ORDER BY avg_fee DESC, d.specialty", true);
  add("Visits per month", "medium", "Dates", "Count visits per month. Return month (YYYY-MM) and visits, oldest month first.", "SELECT strftime('%Y-%m', visit_date) AS month, COUNT(*) AS visits FROM visits GROUP BY month ORDER BY month", true);
  add("Cancellation rate by specialty", "medium", "Conditional aggregate", "For each specialty return cancel_pct: cancelled visits as a percentage of all its visits, 1 decimal. Highest first, ties by specialty.", "SELECT d.specialty, ROUND(100.0 * SUM(CASE WHEN v.status = 'cancelled' THEN 1 ELSE 0 END) / COUNT(*), 1) AS cancel_pct FROM visits v JOIN doctors d ON d.id = v.doctor_id GROUP BY d.specialty ORDER BY cancel_pct DESC, d.specialty", true);
  add("Each patient's latest visit", "hard", "Window functions", "For every patient with a visit return name, visit_date of their most recent visit and the doctor's name (lowest visit id on a tie). Order by patient name.", "SELECT name, visit_date, doctor FROM (SELECT p.name AS name, v.visit_date AS visit_date, d.name AS doctor, ROW_NUMBER() OVER (PARTITION BY p.id ORDER BY v.visit_date DESC, v.id) AS rn FROM visits v JOIN patients p ON p.id = v.patient_id JOIN doctors d ON d.id = v.doctor_id) WHERE rn = 1 ORDER BY name", true);
  add("Doctors above the average earner", "hard", "Subquery", "Doctors' earnings are their completed-visit fees. Return name and total_fees of doctors earning more than the average earnings across all doctors who earned anything. Highest first.", "SELECT name, total_fees FROM (SELECT d.name AS name, SUM(v.fee) AS total_fees FROM visits v JOIN doctors d ON d.id = v.doctor_id WHERE v.status = 'completed' GROUP BY d.id) WHERE total_fees > (SELECT AVG(t) FROM (SELECT SUM(v.fee) AS t FROM visits v WHERE v.status = 'completed' GROUP BY v.doctor_id)) ORDER BY total_fees DESC, name", true);
  add("Patients seeing several specialties", "hard", "HAVING", "List patients who have visited at least 3 different specialties (any status): name and specialties_seen. Most first, ties by name.", "SELECT p.name, COUNT(DISTINCT d.specialty) AS specialties_seen FROM visits v JOIN patients p ON p.id = v.patient_id JOIN doctors d ON d.id = v.doctor_id GROUP BY p.id HAVING COUNT(DISTINCT d.specialty) >= 3 ORDER BY specialties_seen DESC, p.name", true);
}

function rides(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const riders = Array.from({ length: 20 }, (_, i) => [i + 1, person(rng, i + 4), rng.pick(CITIES.slice(0, 4))] as Cell[]);
  const drivers = Array.from({ length: 10 }, (_, i) => [i + 1, person(rng, i + 15), Math.round((3 + rng.next() * 2) * 10) / 10] as Cell[]);
  const trips = Array.from({ length: 90 }, (_, i) => { const km = rng.int(2, 40); return [i + 1, rng.int(1, 17), rng.int(1, 10), isoDate(rng, "2026-02-01", 120), km, km * rng.int(9, 16) + rng.int(0, 5) * 10, rng.weighted([["completed", 8], ["cancelled", 2]] as const)] as Cell[]; });
  tables([table("riders", [num("id"), txt("name"), txt("city")], riders), table("drivers", [num("id"), txt("name"), num("rating", "out of 5")], drivers), table("trips", [num("id"), num("rider_id"), num("driver_id"), date("trip_date"), num("km"), num("fare", "rupees"), txt("status", "completed or cancelled")], trips)]);
  const km = rng.pick([34, 36, 38]);
  add(`Trips over ${km} km`, "easy", "SELECT & WHERE", `List id, km and fare of completed trips longer than ${km} km, longest first (ties by id).`, `SELECT id, km, fare FROM trips WHERE status = 'completed' AND km > ${km} ORDER BY km DESC, id`, true);
  add("Revenue by city", "easy", "JOIN & aggregate", "Add up the fares of completed trips by the rider's city. Return city and revenue, highest first.", "SELECT r.city, SUM(t.fare) AS revenue FROM trips t JOIN riders r ON r.id = t.rider_id WHERE t.status = 'completed' GROUP BY r.city ORDER BY revenue DESC, r.city", true);
  add("Fare per kilometre by driver", "medium", "Aggregate maths", "For each driver with completed trips return name and fare_per_km: total fare divided by total km, 2 decimals. Highest first, ties by name.", "SELECT d.name, ROUND(SUM(t.fare) * 1.0 / SUM(t.km), 2) AS fare_per_km FROM trips t JOIN drivers d ON d.id = t.driver_id WHERE t.status = 'completed' GROUP BY d.id ORDER BY fare_per_km DESC, d.name", true);
  add("Riders without a completed trip", "medium", "NOT EXISTS", "List the riders who have no completed trip, alphabetically.", "SELECT name FROM riders r WHERE NOT EXISTS (SELECT 1 FROM trips t WHERE t.rider_id = r.id AND t.status = 'completed') ORDER BY name", true);
  add("Drivers rated above average", "medium", "Subquery", "List name and rating of drivers whose rating is above the average rating of all drivers. Best first, ties by name.", "SELECT name, rating FROM drivers WHERE rating > (SELECT AVG(rating) FROM drivers) ORDER BY rating DESC, name", true);
  add("Monthly revenue", "medium", "Dates", "Revenue of completed trips per month: month (YYYY-MM) and revenue, oldest first.", "SELECT strftime('%Y-%m', trip_date) AS month, SUM(fare) AS revenue FROM trips WHERE status = 'completed' GROUP BY month ORDER BY month", true);
  add("Each rider's priciest trip", "hard", "Window functions", "For every rider with a completed trip return name and the fare of their most expensive completed trip (lowest trip id on a tie), as top_fare. Order by top_fare descending, then name.", "SELECT name, fare AS top_fare FROM (SELECT r.name AS name, t.fare AS fare, ROW_NUMBER() OVER (PARTITION BY r.id ORDER BY t.fare DESC, t.id) AS rn FROM trips t JOIN riders r ON r.id = t.rider_id WHERE t.status = 'completed') WHERE rn = 1 ORDER BY top_fare DESC, name", true);
  add("Surge-priced trips", "hard", "Subquery", "A trip is surge-priced when its fare per km is more than 1.2 times the average fare per km across all completed trips (each trip's own fare/km, averaged). Return id and fare_per_km (2 decimals) of completed surge trips, highest first, ties by id.", "SELECT id, ROUND(fare * 1.0 / km, 2) AS fare_per_km FROM trips WHERE status = 'completed' AND fare * 1.0 / km > 1.2 * (SELECT AVG(fare * 1.0 / km) FROM trips WHERE status = 'completed') ORDER BY fare_per_km DESC, id", true);
  add("Busy drivers", "medium", "HAVING", "List drivers with at least 8 completed trips: name, trips and avg_fare (1 decimal). Most trips first, ties by name.", "SELECT d.name, COUNT(*) AS trips, ROUND(AVG(t.fare), 1) AS avg_fare FROM trips t JOIN drivers d ON d.id = t.driver_id WHERE t.status = 'completed' GROUP BY d.id HAVING COUNT(*) >= 8 ORDER BY trips DESC, d.name", true);
  add("Running revenue", "hard", "Window functions", "For each trip date with completed trips return trip_date, day_revenue and running_revenue (total up to and including that date). Show only the first 10 dates.", "SELECT trip_date, day_revenue, SUM(day_revenue) OVER (ORDER BY trip_date) AS running_revenue FROM (SELECT trip_date, SUM(fare) AS day_revenue FROM trips WHERE status = 'completed' GROUP BY trip_date) ORDER BY trip_date LIMIT 10", true);
}

function school(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const students = Array.from({ length: 24 }, (_, i) => [i + 1, person(rng, i + 1), rng.pick(["8A", "8B", "9A", "9B"])] as Cell[]);
  const subjects = ["Maths", "Science", "English", "History", "Computing"].map((n, i) => [i + 1, n] as Cell[]);
  const marks: Cell[][] = [];
  for (const st of students.slice(0, 22)) for (const sb of subjects) { if (rng.chance(0.12)) continue; for (const term of ["T1", "T2"]) if (rng.chance(0.95)) marks.push([st[0], sb[0], rng.int(st[0] === 1 || st[0] === 2 ? 45 : 14, 99), term]); }
  tables([table("students", [num("id"), txt("name"), txt("class")], students), table("subjects", [num("id"), txt("name")], subjects), table("marks", [num("student_id"), num("subject_id"), num("score", "out of 100"), txt("term", "T1 or T2")], marks)]);
  const pass = rng.pick([22, 25, 28]);
  add("Class averages", "easy", "GROUP BY", "Return each class with avg_score (average of all its students' scores, 1 decimal). Highest first.", "SELECT s.class, ROUND(AVG(m.score), 1) AS avg_score FROM marks m JOIN students s ON s.id = m.student_id GROUP BY s.class ORDER BY avg_score DESC, s.class", true);
  add(`Scores below ${pass}`, "easy", "JOIN", `List student name, subject and score for every score below ${pass}, lowest first (ties by name, then subject).`, `SELECT s.name, sb.name AS subject, m.score FROM marks m JOIN students s ON s.id = m.student_id JOIN subjects sb ON sb.id = m.subject_id WHERE m.score < ${pass} ORDER BY m.score, s.name, subject`, true);
  add("Topper in each subject", "hard", "Window functions", "For each subject return the student with the highest single score (lowest student id on a tie): subject, name, score. Order by subject.", "SELECT subject, name, score FROM (SELECT sb.name AS subject, s.name AS name, m.score AS score, ROW_NUMBER() OVER (PARTITION BY sb.id ORDER BY m.score DESC, s.id) AS rn FROM marks m JOIN students s ON s.id = m.student_id JOIN subjects sb ON sb.id = m.subject_id) WHERE rn = 1 ORDER BY subject", true);
  add("Never below 40", "medium", "HAVING", "List students whose lowest score across all subjects and terms is at least 40: name and lowest. Highest first, ties by name.", "SELECT s.name, MIN(m.score) AS lowest FROM marks m JOIN students s ON s.id = m.student_id GROUP BY s.id HAVING MIN(m.score) >= 40 ORDER BY lowest DESC, s.name", true);
  add("Rank within class", "hard", "Window functions", "Rank students inside their class by total score (sum of all their scores): class, name, total and class_rank (1 = best; ties share a rank, use RANK). Show only rank 1 and 2. Order by class, rank, name.", "SELECT class, name, total, class_rank FROM (SELECT s.class AS class, s.name AS name, SUM(m.score) AS total, RANK() OVER (PARTITION BY s.class ORDER BY SUM(m.score) DESC) AS class_rank FROM marks m JOIN students s ON s.id = m.student_id GROUP BY s.id) WHERE class_rank <= 2 ORDER BY class, class_rank, name", true);
  add("Term improvement", "hard", "Conditional aggregate", "For each student with scores in both terms return name, t1_avg, t2_avg (1 decimal each) and change (t2_avg - t1_avg, 1 decimal), only for students who improved (change > 0). Biggest change first, ties by name.", "SELECT name, t1_avg, t2_avg, ROUND(t2_avg - t1_avg, 1) AS change FROM (SELECT s.name AS name, ROUND(AVG(CASE WHEN m.term = 'T1' THEN m.score END), 1) AS t1_avg, ROUND(AVG(CASE WHEN m.term = 'T2' THEN m.score END), 1) AS t2_avg FROM marks m JOIN students s ON s.id = m.student_id GROUP BY s.id) WHERE t1_avg IS NOT NULL AND t2_avg IS NOT NULL AND t2_avg > t1_avg ORDER BY change DESC, name", true);
  add("Hardest subject by term", "medium", "GROUP BY", "Return subject, term and avg_score (1 decimal) for the 6 lowest subject-term averages. Lowest first, ties by subject then term.", "SELECT sb.name AS subject, m.term, ROUND(AVG(m.score), 1) AS avg_score FROM marks m JOIN subjects sb ON sb.id = m.subject_id GROUP BY sb.id, m.term ORDER BY avg_score, subject, m.term LIMIT 6", true);
  add("Students with no marks", "medium", "LEFT JOIN", "List the names of students who have no marks recorded, alphabetically.", "SELECT s.name FROM students s LEFT JOIN marks m ON m.student_id = s.id WHERE m.student_id IS NULL ORDER BY s.name", true);
  add("Missing marks", "hard", "NOT EXISTS", "List student name and subject for every subject the student has NO score at all in (in either term), among students who have at least one score. Order by name, subject.", "SELECT s.name, sb.name AS subject FROM students s CROSS JOIN subjects sb WHERE EXISTS (SELECT 1 FROM marks m WHERE m.student_id = s.id) AND NOT EXISTS (SELECT 1 FROM marks m WHERE m.student_id = s.id AND m.subject_id = sb.id) ORDER BY s.name, subject", true);
  add("Grade bands", "medium", "CASE", "Label each score 'A' (80+), 'B' (60-79), 'C' (40-59) or 'F' (below 40). Return grade and scores (how many), ordered by grade.", "SELECT CASE WHEN score >= 80 THEN 'A' WHEN score >= 60 THEN 'B' WHEN score >= 40 THEN 'C' ELSE 'F' END AS grade, COUNT(*) AS scores FROM marks GROUP BY grade ORDER BY grade", true);
}

function inventory(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const warehouses = ["Pune", "Chennai", "Kochi", "Indore"].map((c, i) => [i + 1, c] as Cell[]);
  const catalog: [string, string, number][] = [["Bolt M8", "Hardware", 4], ["Nut M8", "Hardware", 3], ["Drill bit", "Tools", 90], ["Hammer", "Tools", 260], ["Cable 2m", "Electrical", 70], ["Switch", "Electrical", 55], ["Paint 1L", "Paint", 320], ["Brush", "Paint", 45]];
  const items = catalog.map(([n, c, u], i) => [i + 1, n, c, u + rng.int(0, 6)] as Cell[]);
  const stock: Cell[][] = [];
  for (const w of warehouses) for (const it of items) { if (it[0] === 8) stock.push([w[0], it[0], 0]); else if (Number(it[0]) <= 2) stock.push([w[0], it[0], rng.int(1, 200)]); else if (rng.chance(0.75)) stock.push([w[0], it[0], rng.chance(0.15) ? 0 : rng.int(1, 200)]); }
  const moves = Array.from({ length: 70 }, (_, i) => [i + 1, rng.int(1, 8), rng.int(1, 4), (rng.chance(0.5) ? 1 : -1) * rng.int(1, 40), isoDate(rng, "2026-01-01", 150), rng.pick(["purchase", "sale", "damage", "return"])] as Cell[]);
  tables([table("warehouses", [num("id"), txt("city")], warehouses), table("items", [num("id"), txt("name"), txt("category"), num("unit_cost", "rupees")], items), table("stock", [num("warehouse_id"), num("item_id"), num("qty")], stock), table("moves", [num("id"), num("item_id"), num("warehouse_id"), num("qty_change", "negative for stock leaving"), date("moved_on"), txt("reason")], moves)]);
  const low = rng.pick([10, 20, 30]);
  add(`Low stock (under ${low})`, "easy", "JOIN", `List warehouse city, item name and qty for stock lines with fewer than ${low} units, lowest first (ties by city, then item).`, `SELECT w.city, i.name AS item, s.qty FROM stock s JOIN warehouses w ON w.id = s.warehouse_id JOIN items i ON i.id = s.item_id WHERE s.qty < ${low} ORDER BY s.qty, w.city, item`, true);
  add("Stock value by warehouse", "medium", "JOIN & aggregate", "The value of a stock line is qty x unit_cost. Return city and stock_value per warehouse, highest first.", "SELECT w.city, SUM(s.qty * i.unit_cost) AS stock_value FROM stock s JOIN warehouses w ON w.id = s.warehouse_id JOIN items i ON i.id = s.item_id GROUP BY w.id ORDER BY stock_value DESC, w.city", true);
  add("Value by category", "medium", "JOIN & aggregate", "Return category, units (total qty) and value (qty x unit_cost) across all warehouses, highest value first.", "SELECT i.category, SUM(s.qty) AS units, SUM(s.qty * i.unit_cost) AS value FROM stock s JOIN items i ON i.id = s.item_id GROUP BY i.category ORDER BY value DESC, i.category", true);
  add("Items with no stock anywhere", "medium", "NOT EXISTS", "List the names of items that have no units in ANY warehouse (no stock line with qty above 0), alphabetically.", "SELECT name FROM items i WHERE NOT EXISTS (SELECT 1 FROM stock s WHERE s.item_id = i.id AND s.qty > 0) ORDER BY name", true);
  add("Net movement per item", "medium", "GROUP BY", "Return item name and net (sum of qty_change over all movements) for items with movements, lowest net first, ties by name.", "SELECT i.name, SUM(m.qty_change) AS net FROM moves m JOIN items i ON i.id = m.item_id GROUP BY i.id ORDER BY net, i.name", true);
  add("Movements by reason", "easy", "GROUP BY", "Count movements per reason and total units moved (sum of absolute qty_change). Return reason, movements, units; most movements first, ties by reason.", "SELECT reason, COUNT(*) AS movements, SUM(ABS(qty_change)) AS units FROM moves GROUP BY reason ORDER BY movements DESC, reason", true);
  add("Warehouses missing a category", "hard", "NOT EXISTS", "For every warehouse and category where the warehouse holds NO stock line (qty above 0) of any item of that category, return city and category. Order by city, category.", "SELECT w.city, c.category FROM warehouses w CROSS JOIN (SELECT DISTINCT category FROM items) c WHERE NOT EXISTS (SELECT 1 FROM stock s JOIN items i ON i.id = s.item_id WHERE s.warehouse_id = w.id AND i.category = c.category AND s.qty > 0) ORDER BY w.city, c.category", true);
  add("Items held in every warehouse", "hard", "Relational division", "List the names of items that have a stock line with qty above 0 in EVERY warehouse, alphabetically.", "SELECT i.name FROM items i JOIN stock s ON s.item_id = i.id WHERE s.qty > 0 GROUP BY i.id HAVING COUNT(DISTINCT s.warehouse_id) = (SELECT COUNT(*) FROM warehouses) ORDER BY i.name", true);
  add("Running balance of one item", "hard", "Window functions", "For the item with the most movements (lowest id on a tie) return moved_on, qty_change and running_net (cumulative sum ordered by date, ties by movement id). Show the first 10 rows.", "SELECT moved_on, qty_change, SUM(qty_change) OVER (ORDER BY moved_on, id) AS running_net FROM moves WHERE item_id = (SELECT item_id FROM moves GROUP BY item_id ORDER BY COUNT(*) DESC, item_id LIMIT 1) ORDER BY moved_on, id LIMIT 10", true);
  add("Biggest damage loss", "medium", "Subquery", "Movements with reason 'damage' lose stock. Return warehouse city and units_lost (sum of absolute qty_change for damage) for warehouses that lost more than the average warehouse. Most first.", "SELECT w.city, SUM(ABS(m.qty_change)) AS units_lost FROM moves m JOIN warehouses w ON w.id = m.warehouse_id WHERE m.reason = 'damage' GROUP BY w.id HAVING SUM(ABS(m.qty_change)) > (SELECT AVG(t) FROM (SELECT SUM(ABS(qty_change)) AS t FROM moves WHERE reason = 'damage' GROUP BY warehouse_id)) ORDER BY units_lost DESC, w.city", true);
}

function social(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const users = Array.from({ length: 22 }, (_, i) => [i + 1, person(rng, i + 5), isoDate(rng, "2024-01-01", 600), rng.pick(["India", "UAE", "UK", "USA"])] as Cell[]);
  const posts = Array.from({ length: 80 }, (_, i) => [i + 1, rng.int(1, 18), isoDate(rng, "2025-06-01", 240), rng.int(0, 120)] as Cell[]);
  const seen = new Set<string>();
  const follows: Cell[][] = [];
  for (let k = 0; k < 90; k++) { const a = rng.int(1, 22), b = rng.int(1, 22); if (a !== b && !seen.has(`${a}-${b}`)) { seen.add(`${a}-${b}`); follows.push([a, b]); } }
  tables([table("users", [num("id"), txt("name"), date("joined_on"), txt("country")], users), table("posts", [num("id"), num("user_id"), date("posted_on"), num("likes")], posts), table("follows", [num("follower_id"), num("followee_id")], follows)]);
  add("Most active posters", "easy", "GROUP BY", "Return the 5 users with the most posts: name and posts. Ties by name.", "SELECT u.name, COUNT(*) AS posts FROM posts p JOIN users u ON u.id = p.user_id GROUP BY u.id ORDER BY posts DESC, u.name LIMIT 5", true);
  add("Follower counts", "easy", "GROUP BY", "Return each user who has followers: name and followers. Most followers first, ties by name. Show the top 8.", "SELECT u.name, COUNT(*) AS followers FROM follows f JOIN users u ON u.id = f.followee_id GROUP BY u.id ORDER BY followers DESC, u.name LIMIT 8", true);
  add("Users who never posted", "medium", "LEFT JOIN", "List the names of users with no posts, alphabetically.", "SELECT u.name FROM users u LEFT JOIN posts p ON p.user_id = u.id WHERE p.id IS NULL ORDER BY u.name", true);
  add("Mutual follows", "hard", "Self join", "Two users follow each other when both (a, b) and (b, a) exist. List each mutual pair once as user_a and user_b (names), with the lower user id as user_a. Order by user_a, user_b.", "SELECT ua.name AS user_a, ub.name AS user_b FROM follows f1 JOIN follows f2 ON f1.follower_id = f2.followee_id AND f1.followee_id = f2.follower_id JOIN users ua ON ua.id = f1.follower_id JOIN users ub ON ub.id = f1.followee_id WHERE f1.follower_id < f1.followee_id ORDER BY user_a, user_b", true);
  add("Average likes per user", "medium", "GROUP BY", "For users with at least 3 posts return name and avg_likes (1 decimal). Highest first, ties by name.", "SELECT u.name, ROUND(AVG(p.likes), 1) AS avg_likes FROM posts p JOIN users u ON u.id = p.user_id GROUP BY u.id HAVING COUNT(*) >= 3 ORDER BY avg_likes DESC, u.name", true);
  add("Most liked post per user", "hard", "Window functions", "For every user with posts return name and the likes of their most liked post (lowest post id on a tie) as best_likes. Order by best_likes descending, then name. Show the top 10.", "SELECT name, best_likes FROM (SELECT u.name AS name, p.likes AS best_likes, ROW_NUMBER() OVER (PARTITION BY u.id ORDER BY p.likes DESC, p.id) AS rn FROM posts p JOIN users u ON u.id = p.user_id) WHERE rn = 1 ORDER BY best_likes DESC, name LIMIT 10", true);
  add("Posts per month", "medium", "Dates", "Return month (YYYY-MM), posts and total_likes per month, oldest first.", "SELECT strftime('%Y-%m', posted_on) AS month, COUNT(*) AS posts, SUM(likes) AS total_likes FROM posts GROUP BY month ORDER BY month", true);
  add("Popular but quiet", "hard", "Subquery", "List users with at least 4 followers who have posted fewer than 3 times: name, followers and posts (0 if none). Most followers first, ties by name.", "SELECT u.name, (SELECT COUNT(*) FROM follows f WHERE f.followee_id = u.id) AS followers, (SELECT COUNT(*) FROM posts p WHERE p.user_id = u.id) AS posts FROM users u WHERE (SELECT COUNT(*) FROM follows f WHERE f.followee_id = u.id) >= 4 AND (SELECT COUNT(*) FROM posts p WHERE p.user_id = u.id) < 3 ORDER BY followers DESC, u.name", true);
  add("Followers by country", "medium", "JOIN & aggregate", "Count follow relationships grouped by the FOLLOWED user's country: country and follows. Most first, ties by country.", "SELECT u.country, COUNT(*) AS follows FROM follows f JOIN users u ON u.id = f.followee_id GROUP BY u.country ORDER BY follows DESC, u.country", true);
  add("Who follows the most", "easy", "GROUP BY", "Return the 5 users who follow the most people: name and following. Ties by name.", "SELECT u.name, COUNT(*) AS following FROM follows f JOIN users u ON u.id = f.follower_id GROUP BY u.id ORDER BY following DESC, u.name LIMIT 5", true);
}

function hotel(rng: Rng, add: Maker, tables: (t: Dataset[]) => void) {
  const rooms = Array.from({ length: 12 }, (_, i) => [i + 1, rng.pick(["single", "double", "suite"]), (i % 3 + 1) * 1500 + rng.int(0, 4) * 100] as Cell[]);
  const guests = Array.from({ length: 20 }, (_, i) => [i + 1, person(rng, i + 8), rng.pick(["India", "UAE", "UK", "USA", "Nepal"])] as Cell[]);
  const bookings = Array.from({ length: 70 }, (_, i) => [i + 1, rng.int(1, 11), rng.int(1, 17), isoDate(rng, "2026-01-01", 200), rng.int(1, 7), rng.weighted([["stayed", 8], ["cancelled", 2]] as const)] as Cell[]);
  tables([table("rooms", [num("id"), txt("type", "single, double or suite"), num("price_per_night", "rupees")], rooms), table("guests", [num("id"), txt("name"), txt("country")], guests), table("bookings", [num("id"), num("room_id"), num("guest_id"), date("check_in"), num("nights"), txt("status", "stayed or cancelled")], bookings)]);
  add("Revenue by room type", "easy", "JOIN & aggregate", "For stayed bookings, revenue is price_per_night x nights. Return type and revenue per room type, highest first.", "SELECT r.type, SUM(r.price_per_night * b.nights) AS revenue FROM bookings b JOIN rooms r ON r.id = b.room_id WHERE b.status = 'stayed' GROUP BY r.type ORDER BY revenue DESC, r.type", true);
  add("Long stays", "easy", "SELECT & WHERE", "List booking id, guest name and nights for stayed bookings of 5 or more nights, longest first (ties by id).", "SELECT b.id, g.name, b.nights FROM bookings b JOIN guests g ON g.id = b.guest_id WHERE b.status = 'stayed' AND b.nights >= 5 ORDER BY b.nights DESC, b.id", true);
  add("Loyal guests", "medium", "HAVING", "List guests with at least 3 stayed bookings: name and stays. Most first, ties by name.", "SELECT g.name, COUNT(*) AS stays FROM bookings b JOIN guests g ON g.id = b.guest_id WHERE b.status = 'stayed' GROUP BY g.id HAVING COUNT(*) >= 3 ORDER BY stays DESC, g.name", true);
  add("Rooms never booked", "medium", "LEFT JOIN", "List the id and type of rooms with no booking at all, ordered by id.", "SELECT r.id, r.type FROM rooms r LEFT JOIN bookings b ON b.room_id = r.id WHERE b.id IS NULL ORDER BY r.id", true);
  add("Nights sold per month", "medium", "Dates", "For stayed bookings return month of check_in (YYYY-MM) and nights_sold, oldest month first.", "SELECT strftime('%Y-%m', check_in) AS month, SUM(nights) AS nights_sold FROM bookings WHERE status = 'stayed' GROUP BY month ORDER BY month", true);
  add("Average stay by country", "medium", "GROUP BY", "Return each guest country with avg_nights (stayed bookings, 1 decimal) and stays. Highest average first, ties by country.", "SELECT g.country, ROUND(AVG(b.nights), 1) AS avg_nights, COUNT(*) AS stays FROM bookings b JOIN guests g ON g.id = b.guest_id WHERE b.status = 'stayed' GROUP BY g.country ORDER BY avg_nights DESC, g.country", true);
  add("Best guest per country", "hard", "Window functions", "For each country return the guest who spent the most (stayed bookings, price_per_night x nights): country, name, spent. Lowest guest id on a tie. Order by country.", "SELECT country, name, spent FROM (SELECT g.country AS country, g.name AS name, SUM(r.price_per_night * b.nights) AS spent, ROW_NUMBER() OVER (PARTITION BY g.country ORDER BY SUM(r.price_per_night * b.nights) DESC, g.id) AS rn FROM bookings b JOIN guests g ON g.id = b.guest_id JOIN rooms r ON r.id = b.room_id WHERE b.status = 'stayed' GROUP BY g.id) WHERE rn = 1 ORDER BY country", true);
  add("Double-booked rooms", "hard", "Self join", "Two stayed bookings of the same room overlap when one starts before the other ends (a booking occupies check_in up to, not including, check_in + nights). List room_id, and the two booking ids (first_id < second_id) of every overlapping pair. Order by room_id, first_id, second_id.", "SELECT a.room_id, a.id AS first_id, b.id AS second_id FROM bookings a JOIN bookings b ON a.room_id = b.room_id AND a.id < b.id WHERE a.status = 'stayed' AND b.status = 'stayed' AND a.check_in < date(b.check_in, '+' || b.nights || ' days') AND b.check_in < date(a.check_in, '+' || a.nights || ' days') ORDER BY a.room_id, first_id, second_id", true);
  add("Cancellation rate by room type", "medium", "Conditional aggregate", "For each room type return cancel_pct: cancelled bookings as a percentage of all bookings of that type, 1 decimal. Highest first, ties by type.", "SELECT r.type, ROUND(100.0 * SUM(CASE WHEN b.status = 'cancelled' THEN 1 ELSE 0 END) / COUNT(*), 1) AS cancel_pct FROM bookings b JOIN rooms r ON r.id = b.room_id GROUP BY r.type ORDER BY cancel_pct DESC, r.type", true);
  add("Rooms earning above average", "hard", "Subquery", "Each room's revenue is the sum of price_per_night x nights over its stayed bookings. Return id and revenue of rooms earning more than the average across rooms that earned anything. Highest first.", "SELECT id, revenue FROM (SELECT r.id AS id, SUM(r.price_per_night * b.nights) AS revenue FROM bookings b JOIN rooms r ON r.id = b.room_id WHERE b.status = 'stayed' GROUP BY r.id) WHERE revenue > (SELECT AVG(t) FROM (SELECT SUM(r.price_per_night * b.nights) AS t FROM bookings b JOIN rooms r ON r.id = b.room_id WHERE b.status = 'stayed' GROUP BY r.id)) ORDER BY revenue DESC, id", true);
}

export const WORLDS = { shop, hr, campus, flights, library, streaming, logs, bank, hospital, rides, school, inventory, social, hotel } as const;
export type WorldKey = keyof typeof WORLDS;

/** Every task one world produces for one data seed. The same (world, seed) always gives the same tasks. */
export function buildWorld(world: WorldKey, seed: number): SqlTaskDef[] {
  const rng = makeRng(seed * 7919 + Object.keys(WORLDS).indexOf(world) * 104729 + 17);
  let built: Dataset[] = [];
  const out: SqlTaskDef[] = [];
  const add: Maker = (title, difficulty, category, prompt, query, ordered, tags = []) => out.push({ title, category, difficulty, prompt, query, ordered, tables: [], tags: [world, category.toLowerCase(), ...tags] });
  WORLDS[world](rng, add, (t) => { built = t; });
  return out.map((t) => ({ ...t, tables: built }));
}

export const WORLD_KEYS = Object.keys(WORLDS) as WorldKey[];
